#!/usr/bin/env python3
"""Structured random generator: atoms biased to be true on training data."""
import json, random

NUM = ('TIME','SIZE','COUNT')

def gen_request(rng, small_probes=True):
    K = rng.choice([1,1,2,2,2,3,3,4,5,8])
    nf = rng.randint(1,4)
    schema = []
    ftypes = []
    for i in range(nf):
        ty = rng.choice(['TIME','SIZE','COUNT','ID','FLAG'])
        nm = 'f%d' % i
        if ty in NUM:
            lo = rng.choice([0, -5, 1]); hi = rng.choice([lo+3, lo+10, lo+50])
            schema.append({'name':nm,'type':ty,'min':lo,'max':hi})
        elif ty == 'ID':
            pool = ['a','b','c','d'][:rng.randint(2,4)]
            schema.append({'name':nm,'type':'ID','values':pool})
        else:
            schema.append({'name':nm,'type':'FLAG'})
        ftypes.append(ty)
    fmin = [f.get('min') for f in schema]
    fmax = [f.get('max') for f in schema]
    fvals = [f.get('values') for f in schema]

    # ---- data ----
    nsrc = rng.randint(1,3)
    srcs = ['s%d' % i for i in range(nsrc)]
    def mk_rows(n, mode):
        rows = []
        ts = rng.sample(range(0, 200), n)
        base = {}
        for i,f in enumerate(schema):
            if ftypes[i] in NUM:
                base[i] = rng.randint(fmin[i], fmax[i])
        for t in ts:
            vals = []
            for i,f in enumerate(schema):
                ty = ftypes[i]
                if ty == 'FLAG':
                    vals.append(rng.random() < rng.choice([0.2,0.5,0.8]))
                elif ty == 'ID':
                    vals.append(rng.choice(fvals[i]))
                else:
                    if mode == 'tight' and rng.random() < 0.7:
                        vals.append(base[i])
                    else:
                        vals.append(rng.randint(fmin[i], fmax[i]))
            rows.append({'t':t,'values':vals})
        rng.shuffle(rows)
        return rows

    parts = {}
    tid = 0
    for key in ('train','probes','queries'):
        traces = []
        if key == 'probes' and small_probes:
            counts = [rng.choice([0,1,1,1,2])]
        elif key == 'train':
            counts = [rng.randint(1,3) for _ in range(rng.randint(1,3))]
        else:
            counts = [rng.randint(0,2) for _ in range(rng.randint(1,2))]
        for _ in range(rng.choice(counts) if key=='probes' else len(counts)):
            pass
        ntr = {'train':rng.randint(1,3),'probes':rng.choice([1,1,2]),
               'queries':rng.randint(1,2)}[key]
        for _ in range(ntr):
            if key == 'probes':
                n = rng.choice([K-1, K, K, K+1])
            else:
                n = rng.choice([K-1, K, K, K+1, K+2])
            n = max(0, n)
            traces.append({'id':'t%d'%tid,'source':rng.choice(srcs),
                           'rows':mk_rows(n, 'tight' if key=='train' else 'loose')})
            tid += 1
        parts[key] = traces

    # helper to evaluate candidate atoms on training contexts
    sys_path = None
    import reference
    def truth_of(atom):
        try:
            f = reference.mk_atom(atom, K, {f['name']:(i,f['type']) for i,f in enumerate(schema)})
        except Exception:
            return None
        ctxs = []
        for tr in parts['train']:
            rows = tr['rows']
            if len(rows) < K: continue
            srt = sorted(rows, key=lambda r:r['t'])
            vals=[r['values'] for r in srt]
            for i in range(len(rows)-K+1):
                ctxs.append(vals[i:i+K])
        try:
            return [f(c) for c in ctxs]
        except Exception:
            return None

    # ---- atom templates ----
    def const_for(i, frac):
        ty = ftypes[i]
        if ty in NUM:
            return fmin[i] + int((fmax[i]-fmin[i])*frac)
        if ty == 'FLAG':
            return frac < 0.5
        return rng.choice(fvals[i])

    def mk_atom_candidate():
        i = rng.randrange(nf)
        ty = ftypes[i]
        at = rng.randrange(K)
        kind = rng.choice(['ge','le','eq','ne','self','agg','quant','add'])
        if kind in ('ge','le','eq','ne') and ty in NUM:
            op = kind if kind != 'ne' else rng.choice(['ge','le'])
            return {'cmp':op,'left':{'field':'f%d'%i,'at':at},
                    'right':{'const':const_for(i, rng.choice([0.0,0.1,0.3,0.5,0.7,0.9,1.0])),'type':ty}}
        if kind in ('eq','ne'):
            return {'cmp':kind,'left':{'field':'f%d'%i,'at':at},
                    'right':{'const':const_for(i, rng.choice([0.0,0.3,0.7])),'type':ty}}
        if kind == 'self':
            at2 = rng.randrange(K)
            op = 'eq' if rng.random()<0.7 else rng.choice(['ge','le','ne'])
            if ty not in NUM and op not in ('eq','ne'): op='eq'
            return {'cmp':op,'left':{'field':'f%d'%i,'at':at},
                    'right':{'field':'f%d'%i,'at':at2}}
        if kind == 'agg' and ty in NUM:
            a = rng.randrange(K); b = rng.randrange(a,K)
            op = rng.choice(['sum','mean','min','max'])
            agg = {'aggregate':op,'field':'f%d'%i,'from':a,'to':b}
            return {'cmp':rng.choice(['ge','le']), 'left':agg,
                    'right':{'const':const_for(i, rng.choice([0.0,0.2,0.5,0.8,1.0])),'type':ty}}
        if kind == 'add' and ty in NUM:
            at2 = rng.randrange(K)
            t = {'add':[{'field':'f%d'%i,'at':at},{'field':'f%d'%i,'at':at2}]}
            if rng.random()<0.3:
                t = {'scale':rng.randint(1,3),'term':t}
            return {'cmp':rng.choice(['ge','le']), 'left':t,
                    'right':{'const':const_for(i, rng.choice([0.0,0.3,0.6,1.0])),'type':ty}}
        if kind == 'quant':
            a = rng.randrange(K); b = rng.randrange(a,K)
            bodyop = rng.choice(['ge','le','eq'])
            if ty not in NUM and bodyop not in ('eq','ne'): bodyop='eq'
            return {'quantifier':rng.choice(['any','all']),'from':a,'to':b,
                    'predicate':{'cmp':bodyop,
                                 'left':{'field':'f%d'%i,'at':'$' if rng.random()<0.8 else rng.randrange(K)},
                                 'right':{'const':const_for(i, rng.choice([0.0,0.2,0.5,0.8])),'type':ty}}}
        # fallback
        if ty in NUM:
            return {'cmp':'ge','left':{'field':'f%d'%i,'at':at},
                    'right':{'const':fmin[i],'type':ty}}
        if ty == 'FLAG':
            return {'cmp':'eq','left':{'field':'f%d'%i,'at':at},
                    'right':{'const':True,'type':'FLAG'}}
        return {'cmp':'eq','left':{'field':'f%d'%i,'at':at},
                'right':{'const':fvals[i][0],'type':'ID'}}

    natoms = rng.randint(1,5)
    atoms = []
    tries = 0
    while len(atoms) < natoms and tries < 200:
        tries += 1
        cand = mk_atom_candidate()
        tv = truth_of(cand)
        if tv is None or not tv:
            continue
        rate = sum(tv)/len(tv) if tv else 0
        if rate >= rng.choice([1.0,1.0,0.75,0.6]):
            atoms.append(cand)
    # sometimes duplicate an atom verbatim (distinct indices)
    if atoms and rng.random() < 0.4:
        atoms.append(json.loads(json.dumps(rng.choice(atoms))))
    rng.shuffle(atoms)
    atoms = atoms[:20]

    pol = {'max_width':rng.randint(1,4),
           'min_support':rng.randint(1,3),
           'min_witness':rng.randint(1,2)}
    return {'version':1,'schema':schema,'window':K,'atoms':atoms,'policy':pol,
            'train':parts['train'],'probes':parts['probes'],'queries':parts['queries']}

if __name__ == '__main__':
    import sys
    rng = random.Random(int(sys.argv[1]))
    json.dump(gen_request(rng), sys.stdout)
